  "inlineSchema": "// ============================================================\n// Schéma de base de données - Smart Campus (NextCampus)\n//\n// Sprint 0 : on pose les fondations (User, Role, Class).\n// Les entités Subject, Schedule, Absence, Grade, Announcement,\n// Resource, Booking seront ajoutées au fil des sprints suivants\n// (voir 01-cahier-des-charges.md, section 5 et 6).\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  STUDENT\n  TEACHER\n  ADMIN\n}\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String // stocké hashé (bcrypt) - jamais en clair\n  firstName String\n  lastName  String\n  role      Role     @default(STUDENT)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Un étudiant appartient à une classe (nullable pour enseignants/admins)\n  classId String?\n  class   Class?  @relation(fields: [classId], references: [id])\n\n  // Relations inverses (un enseignant peut enseigner plusieurs matières ;\n  // un étudiant peut avoir plusieurs absences/notes)\n  subjectsTaught        Subject[]\n  absences              Absence[]      @relation(\"StudentAbsences\")\n  grades                Grade[]        @relation(\"StudentGrades\")\n  announcementsAuthored Announcement[] @relation(\"AnnouncementsAuthored\")\n  bookings              Booking[]      @relation(\"UserBookings\")\n\n  @@map(\"users\")\n}\n\nmodel Class {\n  id        String   @id @default(uuid())\n  name      String // ex: \"DEV-B3-A\"\n  year      Int // ex: 2026 (année de promotion)\n  createdAt DateTime @default(now())\n\n  students      User[]\n  subjects      Subject[]\n  schedule      ScheduleEntry[]\n  announcements Announcement[]\n\n  @@map(\"classes\")\n}\n\n// Une matière est rattachée à une classe et à un enseignant (optionnel\n// à la création : un admin peut créer la matière avant d'assigner\n// l'enseignant).\nmodel Subject {\n  id        String   @id @default(uuid())\n  name      String // ex: \"Développement Web\"\n  createdAt DateTime @default(now())\n\n  classId String\n  class   Class  @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  teacherId String?\n  teacher   User?   @relation(fields: [teacherId], references: [id])\n\n  schedule ScheduleEntry[]\n  absences Absence[]\n  grades   Grade[]\n\n  @@map(\"subjects\")\n}\n\nenum DayOfWeek {\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n}\n\n// Un créneau récurrent dans l'emploi du temps (ex : \"Développement Web,\n// tous les lundis de 9h à 12h, salle B12\").\nmodel ScheduleEntry {\n  id        String    @id @default(uuid())\n  dayOfWeek DayOfWeek\n  startTime String // format \"HH:mm\", ex: \"09:00\"\n  endTime   String // format \"HH:mm\", ex: \"12:00\"\n  room      String\n\n  classId String\n  class   Class  @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  subjectId String\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@map(\"schedule_entries\")\n}\n\nmodel Absence {\n  id        String   @id @default(uuid())\n  date      DateTime\n  justified Boolean  @default(false)\n  comment   String?\n  createdAt DateTime @default(now())\n\n  studentId String\n  student   User   @relation(\"StudentAbsences\", fields: [studentId], references: [id], onDelete: Cascade)\n\n  subjectId String\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@map(\"absences\")\n}\n\nmodel Grade {\n  id       String   @id @default(uuid())\n  value    Float // note obtenue\n  maxValue Float    @default(20) // barème, 20 par défaut\n  comment  String?\n  date     DateTime @default(now())\n\n  studentId String\n  student   User   @relation(\"StudentGrades\", fields: [studentId], references: [id], onDelete: Cascade)\n\n  subjectId String\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  @@map(\"grades\")\n}\n\n// Une annonce est soit globale (classId = null, visible de tous), soit\n// ciblée sur une classe précise. Publiée par un enseignant ou un admin.\nmodel Announcement {\n  id        String   @id @default(uuid())\n  title     String\n  content   String\n  createdAt DateTime @default(now())\n\n  authorId String\n  author   User   @relation(\"AnnouncementsAuthored\", fields: [authorId], references: [id], onDelete: Cascade)\n\n  classId String? // null = annonce globale, visible par tout le monde\n  class   Class?  @relation(fields: [classId], references: [id], onDelete: Cascade)\n\n  @@map(\"announcements\")\n}\n\nenum ResourceType {\n  ROOM\n  EQUIPMENT\n}\n\n// Une ressource réservable : salle de travail, vidéoprojecteur, etc.\nmodel Resource {\n  id       String       @id @default(uuid())\n  name     String\n  type     ResourceType\n  capacity Int? // pertinent pour une salle, pas pour du matériel\n\n  bookings Booking[]\n\n  @@map(\"resources\")\n}\n\nmodel Booking {\n  id        String   @id @default(uuid())\n  date      DateTime // jour de la réservation\n  startTime String // format \"HH:mm\"\n  endTime   String // format \"HH:mm\"\n  purpose   String?\n  createdAt DateTime @default(now())\n\n  resourceId String\n  resource   Resource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(\"UserBookings\", fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"bookings\")\n}\n",
  "inlineSchemaHash": "c4c8c129d4cd91b665f2d08b37b8822cd824f1285954bd4f0ac504dec6deaa24",
